'use strict';

/**
 * GET /api/market-energy-narrative
 *
 * Returns the latest AI decision intelligence result saved by the hourly cron.
 * The result is generated by src/narrativeEngine.js and stored in market_energy_narrative.
 */

const { cors, getClient } = require('./_db');

module.exports = async function handler(req, res) {
  cors(res);
  if (req.method === 'OPTIONS') return res.status(200).end();
  if (req.method !== 'GET')    return res.status(405).json({ error: 'GET only' });

  try {
    const sb = getClient();
    const { data, error } = await sb
      .from('market_energy_narrative')
      .select('result, computed_at')
      .eq('id', 1)
      .single();

    if (error || !data) return res.json(null);
    res.json(data.result);
  } catch (e) {
    console.error('[ME-NARRATIVE]', e.message);
    res.status(500).json({ error: e.message });
  }
};
